import{_ as t,o as a,c as r,a0 as i}from"./chunks/framework.DPd3ST4h.js";const p=JSON.parse('{"title":"Redline","description":"Automated pull request review for GitHub","frontmatter":{"title":"Redline","description":"Automated pull request review for GitHub"},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1792931915000}'),o={name:"index.md"};function n(d,e,s,l,u,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="redline" tabindex="-1">Redline <a class="header-anchor" href="#redline" aria-label="Permalink to &quot;Redline&quot;">​</a></h1><p>Automated pull request review, smaller and self-hosted. A GitHub Action reviews a pull request&#39;s changed files with a fixed review policy through a harness executor (Pi or OpenCode), validates every finding against the diff, and publishes the review output as artifacts — or as GitHub reviews and comments when a publication token is supplied.</p><h2 id="how-a-review-runs" tabindex="-1">How a review runs <a class="header-anchor" href="#how-a-review-runs" aria-label="Permalink to &quot;How a review runs&quot;">​</a></h2><p>The action fetches the pull request&#39;s base and head commits as Git data, builds a bounded context bundle, and runs one fixed review prompt per eligible changed file through the selected harness. Lock files, vendored and generated directories (for example <code>node_modules/</code> or <code>dist/</code>), and binary files are excluded from review and recorded as unreviewed, so their changes stay identifiable in the manifest. The harness runs with every tool disabled and isolated generated configuration; no ambient credentials reach it. Each model finding must map its span (<code>file:x-y</code>) to changed lines of the authoritative diff with matching evidence, or it is rejected; validated findings carry a change suggestion and a fix prompt for coding agents. Pull request code is never executed.</p><h2 id="start-here" tabindex="-1">Start here <a class="header-anchor" href="#start-here" aria-label="Permalink to &quot;Start here&quot;">​</a></h2><ul><li><a href="/projects/redline/reusable-review-workflow">Reusable review workflow</a> — call Redline from your repository&#39;s <code>pull_request_target</code> workflow.</li><li><a href="/projects/redline/dogfood-review">Dogfood reviews</a> — how Redline reviews and publishes results on its own pull requests.</li><li><a href="/projects/redline/github-composite-action">GitHub composite action</a> — the full input contract, secrets, pipeline, and boundaries.</li></ul><h2 id="how-it-works-under-the-hood" tabindex="-1">How it works under the hood <a class="header-anchor" href="#how-it-works-under-the-hood" aria-label="Permalink to &quot;How it works under the hood&quot;">​</a></h2><ul><li><a href="/projects/redline/runnable-review-configuration">Runnable review configuration</a> — the environment contract, <code>model-config</code>, and <code>model-auth</code>.</li><li><a href="/projects/redline/harness-executor">Harness executor</a> — how Pi and OpenCode are configured and driven, and how to add a harness.</li><li><a href="/projects/redline/review-reporting">Review output</a> — per-file review records, validation, and the run summary.</li><li><a href="/projects/redline/performance-benchmark">Performance benchmark</a> — the fixed 20-file latency baseline, telemetry, and live SLO capture.</li><li><a href="/projects/redline/model-execution-benchmark">Model execution benchmark</a> — Pi thinking, output-token, structured-output, deadline, retry, cost, and process-isolation evidence.</li></ul><h2 id="status" tabindex="-1">Status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;Status&quot;">​</a></h2><p>The GitHub entry point with artifact output and per-file GitHub publication is complete. The container sandbox, managed local model runtimes, and Forgejo/Gitea entry points are planned sequenced milestones. See <a href="https://github.com/dragoscirjan/redline/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer">CONTRIBUTING.md</a> for the development workflow and the GitHub issue tracker for open work.</p>',10)])])}const f=t(o,[["render",n]]);export{p as __pageData,f as default};
